<template>
  <q-checkbox
    v-bind="props"
    :label="
      isOuter ? undefined : meta_field.label ? $t(meta_field.label) : '&nbsp;'
    "
    :class="[props.class, additionalClass]"
    :model-value="modelValue"
    @update:model-value="emit('update:modelValue', $event)"
    :inline="meta_field.label_style === 'inline'"
  >
  </q-checkbox>
</template>
<script lang="ts">
import { defineComponent, ref } from 'vue';
import type { CheckboxMetaField } from 'src/supplier/types/meta';
export default defineComponent({
  el: '#app',
  props: {
    meta_field: {
      type: Object as () => CheckboxMetaField,
      required: true,
    },
    name: {
      type: String as () => CheckboxMetaField['type'],
      required: true,
    },
    type: {
      type: String,
      required: true,
    },
    label: {
      type: String,
      required: false,
    },
    rules: {
      type: Array as () => CheckboxMetaField['rules'],
      required: true,
    },
    class: {
      type: String,
      required: false,
      default: '',
    },
    disable: {
      type: Boolean,
      required: true,
    },
    readonly: {
      type: Boolean,
      required: true,
    },
    modelValue: {
      type: Boolean,
      default: false,
    },
    stackLabel: {
      type: Boolean,
      required: true,
    },
    dense: {
      type: Boolean,
      required: true,
    },
    hideBottomSpace: {
      type: Boolean,
      required: true,
    },
    reactiveRule: {
      type: Boolean,
      required: false,
    },
    asterisk: {
      type: String,
      required: false,
    },
    labelSlot: {
      type: Boolean,
      required: false,
    },
    isOuter: {
      type: Boolean,
      required: false,
    },
  },
  emits: ['update:modelValue'],
  setup(props, { emit }) {
    return {
      additionalClass: ref(''),
      props,
      emit,
    };
  },
});
</script>
