<template>
  <q-input
    v-bind="props"
    :type="type.toLowerCase() as any"
    :class="[props.class, additionalClass, 'builder-form-input']"
    :placeholder="meta_field.placeholder"
    :model-value="modelValue ?? ''"
    @update:model-value="emit('update:modelValue', $event)"
    :outlined="
      meta_field.design === 'outlined' ||
      meta_field.design === 'outlined-filled'
    "
    :border-less="meta_field.design === 'borderless'"
    :standout="meta_field.design === 'standout'"
    :filled="meta_field.design === 'filled'"
    :mask="meta_field.mask"
    :fill-mask="meta_field.fillMask ?? false"
    :hint="meta_field.hint"
    :maxlength="meta_field.maxlength"
    :rules="[
      ...(meta_field.minlength
        ? [
            (val: string) =>
              min(val, meta_field.minlength) ||
              $t(`supplier_register_form.error.minlength_error`) +
                ` ${meta_field.minlength}`,
          ]
        : []),
      ...rules,
    ]"
  >
    <template v-if="meta_field.beforeIcon" v-slot:prepend>
      <q-icon :name="meta_field.beforeIcon" />
    </template>
    <template v-if="meta_field.afterIcon" v-slot:append>
      <q-icon :name="meta_field.afterIcon" />
    </template>
    <template v-if="!props.isOuter" v-slot:label>
      {{ meta_field.title ? $t(meta_field.title) : '&nbsp;' }}
      <span class="text-red">&nbsp;{{ asterisk }}</span>
    </template>
  </q-input>
</template>

<script setup lang="ts">
import { InputMetaField, MetaKeys } from 'src/supplier/types/meta';
import { QInputProps, QSelect } from 'quasar';
import { min } from 'src/supplier/utils/validator';
import { RegisterStep } from 'src/supplier/types';

type TextFieldProps = {
  meta_field: any;
  name: string;
  type: InputMetaField['type'];
  label?: string;
  rules: QInputProps['rules'];
  class?: string;
  disable: boolean;
  readonly: boolean;
  modelValue?: string;
  stackLabel: boolean;
  dense: boolean;
  hideBottomSpace: boolean;
  asterisk?: string;
  reactiveRule?: boolean;
  labelSlot?: boolean;
  isOuter?: boolean;
};

const props = defineProps<TextFieldProps>();
const emit = defineEmits(['update:modelValue']);

 
const { meta_field } = props;

const outlinedFilled =
  meta_field.design === 'outlined-filled' ? 'bg-grey-5' : '';
const inlineLabel =
  meta_field.label_style === 'inline' ? 'flex q-col-gutter-xl' : '';
const additionalClass = `${outlinedFilled} ${inlineLabel}`;
</script>
<style scoped>
.builder-form-input,
.q-field--dense .q-field__control {
  height: auto !important;
}
</style>
