<template>
  <q-select
    v-bind="$props as any"
    :class="[$props.class, additionalClass]"
    :options="filterOption"
    v-model="internalValue"
    :inline="meta_field.label_style === 'inline'"
    :outlined="
      meta_field.design === 'outlined' ||
      meta_field.design === 'outlined-filled'
    "
    :border-less="meta_field.design === 'borderless'"
    :standout="meta_field.design === 'standout'"
    :filled="meta_field.design === 'filled'"
    :behavior="meta_field.behavior || 'default'"
    :hint="meta_field.hint"
    :hide-dropdown-icon="isSearch"
    :use-input="isSearch"
    @filter="filterFn"
    autocomplete=""
    map-options
    emit-value
    option-value="value"
    option-label="label"
    hide-hint
    @keyup.delete="clearValue"
  >
    <template v-if="meta_field.beforeIcon" v-slot:prepend>
      <q-icon :name="meta_field.beforeIcon" />
    </template>
    <template v-slot:append>
      <q-icon v-if="meta_field.hint" name="info">
        <q-tooltip>{{
          $t(`${translationKey}.hint.${meta_field.hint}`)
        }}</q-tooltip>
      </q-icon>
      <q-icon
        v-if="meta_field.afterIcon || isSearch"
        :name="(meta_field.afterIcon ?? isSearch) ? 'search' : undefined"
      />
    </template>
    <template v-if="!isOuter" v-slot:label>
      {{ meta_field.title ? $t(meta_field.title) : '&nbsp;' }}
      <span class="text-red">&nbsp;{{ asterisk }}</span>
    </template>
    <template v-slot:no-option>
      <q-item>
        <q-item-section class="text-grey"> No results </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import { QSelect } from 'quasar';
import { SelectMetaField } from 'src/supplier/types/meta';
import { Option } from 'src/supplier/types';
import { useSettingStore } from 'src/store/main';
import { supplier_statuses } from 'src/constants';
import { i18n } from 'src/boot/i18n';

export default defineComponent({
  name: 'SelectField',
  props: {
    meta_field: {
      type: Object as PropType<any>,
      required: true,
    },
    name: {
      type: String,
      required: true,
    },
    label: {
      type: String,
      default: '',
    },
    rules: {
      type: Array as PropType<SelectMetaField['rules']>,
      default: () => [],
    },
    class: {
      type: String,
      default: '',
    },
    disable: {
      type: [Boolean, Function] as PropType<SelectMetaField['disable']>,
      default: false,
    },
    readonly: {
      type: Boolean,
      default: false,
    },
    stackLabel: {
      type: Boolean,
      default: false,
    },
    dense: {
      type: Boolean,
      default: false,
    },
    hideBottomSpace: {
      type: Boolean,
      default: false,
    },
    reactiveRule: {
      type: Boolean,
      default: false,
    },
    labelSlot: {
      type: Boolean,
      default: false,
    },
    asterisk: {
      type: String,
      default: '',
    },
    isOuter: {
      type: Boolean,
      default: false,
    },
    hint: {
      type: String,
      default: '',
    },
    translationKey: {
      type: String,
      required: true,
    },
    modelValue: {
      type: [String, Number, Object, Array] as PropType<any>,
      default: null,
    },
  },
  emits: ['update:modelValue'],
  setup() {
    const setting_store = useSettingStore();

    return {
      setting_store,
    };
  },
  data() {
    return {
      filterOption: [] as Option[],
      additionalClass: '',
      isSearch: false,
      internalValue: null as any,
    };
  },
  watch: {
    modelValue(newVal) {
      this.internalValue = newVal;
    },
    internalValue(newVal) {
      this.$emit('update:modelValue', newVal);
    },
  },
  mounted() {
    this.internalValue = this.modelValue;
    this.additionalClass = this.getAdditionalClass();
    this.isSearch = this.getIsSearch();
    this.filterOption = this.getOptions();
  },
  methods: {
    getStatusOptions(): Option[] {
      try {
        const settingValue = this.setting_store.user_settings[supplier_statuses];
        if (!settingValue) return [];
        const rawOptions = JSON.parse(settingValue);
        return rawOptions.map((option: any) => {
          const key = String(option.value).toLowerCase();
          const translatedLabel = i18n.t(key);
          return {
            ...option,
            label: translatedLabel === key ? option.value : translatedLabel,
          };
        });
      } catch (e) {
        return [];
      }
    },
    getOptions(): Option[] {
      if (this.meta_field.field_name === 'status') {
        let options = this.getStatusOptions();

        // If current modelValue is not in options, add it as a translated option
        // This handles cases where the status exists but isn't in the dropdown settings
        if (this.modelValue && !options.find((opt: any) => opt.value === this.modelValue)) {
          const currentValue = String(this.modelValue);
          const key = currentValue.toLowerCase();
          const translatedLabel = i18n.t(key);
          options = [
            {
              value: currentValue,
              label: translatedLabel === key ? currentValue : translatedLabel,
            } as Option,
            ...options,
          ];
        }
        return options;
      }
      return this.meta_field.options || [];
    },
    filterFn(val: string, update: (fn: () => void) => void) {
      update(() => {
        const needle = val.toLowerCase();
        this.filterOption = this.getOptions()?.filter(
          (v: Option) => v.label?.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
    clearValue() {
      this.internalValue = null;
      this.$emit('update:modelValue', null);
    },
    getAdditionalClass(): string {
      const outlinedFilled =
        this.meta_field.design === 'outlined-filled' ? 'bg-grey-5' : '';
      const inlineLabel =
        this.meta_field.label_style === 'inline' ? 'flex q-col-gutter-xl' : '';
      return `${outlinedFilled} ${inlineLabel}`;
    },
    getIsSearch(): boolean {
      return ['search', 'SEARCH'].includes(this.meta_field.type);
    },
  },
});
</script>
