<template>
  <q-option-group
    v-bind="props"
    :class="[props.class, additionalClass]"
    :options="options"
    :model-value="modelValue"
    @update:model-value="emit('update:modelValue', $event)"
    :inline="meta_field.label_style === 'inline'"
    :label="props.label"
  >
    <template v-if="!props.isOuter" v-slot:label="">
      {{
        meta_field.label
          ? $t(`supplier_register_form.field.${meta_field.label}`)
          : '&nbsp;'
      }}
      <span class="text-red">&nbsp;{{ asterisk }}</span>
    </template>
  </q-option-group>
</template>

<script setup lang="ts">
import type { OptionMetaField } from 'src/supplier/types/meta';
import { computed } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { RegisterStep, MetaKeys } from 'src/supplier/types';
import { QOptionGroupProps } from 'quasar';
const { t } = useTranslate();

type TextFieldProps = {
  meta_field: OptionMetaField;
  name: string;
  type: QOptionGroupProps['type'];
  label?: string;
  rules: OptionMetaField['rules'];
  class?: string;
  disable: OptionMetaField['disable'];
  readonly: boolean;
  modelValue: any;
  stackLabel: boolean;
  dense: boolean;
  hideBottomSpace: boolean;
  reactiveRule?: boolean;
  asterisk?: string;
  labelSlot?: boolean;
  isOuter?: boolean;
};

const props = defineProps<TextFieldProps>();
const emit = defineEmits(['update:modelValue']);

 
const { meta_field } = props;

const additionalClass = 'q-col-gutter-xl';
const options = computed(() => {
  return meta_field.options?.map((option) => {
    return {
      label: t.value('supplier_register_form.field.' + option.label),
      value: option.value,
    };
  });
});
</script>
