<template>
  <q-file
    ref="fileRef"
    v-bind="props as any"
    :class="[props.class, additionalClass]"
    :accept="meta_field.accept"
    :model-value="modelValue"
    @update:model-value="updateFile($event)"
    :outlined="
      meta_field.design === 'outlined' ||
      meta_field.design === 'outlined-filled'
    "
    :borderless="meta_field.design === 'borderless'"
    :standout="meta_field.design === 'standout'"
    :filled="meta_field.design === 'filled'"
    :hint="meta_field.hint"
    :error="props.isError || status?.status === 'error'"
    lazy-rules="ondemand"
    no-error-icon
    :label-slot="!modelValue"
  >
    <template
      v-if="status?.status !== 'none' || meta_field.beforeIcon"
      v-slot:prepend
    >
      <q-icon v-if="status?.status === 'error'" name="error" color="warning" />
      <q-icon
        v-else-if="status?.status === 'uploaded'"
        name="check_circle"
        color="positive"
      />
      <q-icon
        v-else-if="status?.status === 'loading'"
        name="img:/images/supplier_file_loading.png"
        class="spin"
      />
      <q-icon v-else :name="meta_field.beforeIcon" />
    </template>
    <template v-slot:append>
      <div class="flex q-col-gutter-sm">
        <q-icon
          name="visibility"
          @click.stop.prevent="previewFile"
          :class="[!isDisable && 'cursor-pointer text-primary']"
        />
        <q-icon
          v-if="!props.readonly"
          name="cloud_upload"
          @click.stop.prevent="pickFile"
          class="cursor-pointer text-primary"
        />
        <q-icon
          v-if="!props.readonly"
          name="delete"
          @click.stop.prevent="clearFile"
          :class="[!isDisable && 'cursor-pointer text-primary']"
        />
        <q-icon v-if="meta_field.afterIcon" :name="meta_field.afterIcon" />
      </div>
    </template>
    <template v-if="!modelValue" v-slot:label>
      {{ displayFileName }} <span class="text-red">{{ asterisk }}</span>
    </template>
    <template v-slot:error>
      <span class="listing-header">{{ $t('error_file_uploading_title') }}</span>
      <ul class="error-listing">
        <li v-for="(item, index) in status.errorMessage" :key="index">
          {{ item }}
        </li>
      </ul>
    </template>
  </q-file>

  <!--  PDF PREVIEW DIALOG -->
  <PdfPreviewDialog v-model="dialog" :url="currentPdfUrl" />
</template>

<script setup lang="ts">
import { storeToRefs } from 'pinia';
import { FileMetaField } from 'src/supplier/types/meta';
import { computed, ref, toRef, watch } from 'vue';
import { QFile } from 'quasar';
import { useRoute } from 'vue-router';
import PdfPreviewDialog from 'src/supplier/components/dynamic/form/PdfPreviewDialog.vue';
import { ApiError } from 'src/errors';
import { ArrayError } from 'src/supplier/utils/ArrayError';
import { i18n } from 'src/boot/i18n';
import { RegisterStep } from 'src/supplier/types';
import { useSupplierLayoutsStore } from 'src/store/main';
import { log } from 'util';

const $route = useRoute();

const supplier_layouts_store = useSupplierLayoutsStore();
const { supplierUploadStatus, formConfigure } = storeToRefs(
  supplier_layouts_store,
);
const { uploadFile, deleteFile, updateSupplier } = useSupplierLayoutsStore();

type TextFieldProps = {
  meta_field: FileMetaField;
  name: string;
  type: FileMetaField['type'];
  label?: string;
  rules: FileMetaField['rules'];
  class?: string;
  disable: boolean;
  readonly: boolean;
  modelValue: File | null;
  stackLabel: boolean;
  dense: boolean;
  hideBottomSpace: boolean;
  reactiveRule?: boolean;
  labelSlot?: boolean;
  isError?: boolean;
  errorMessage?: string | string[];
  translationKey?: string;
  asterisk?: string;
  isOuter?: boolean;
};

const props = defineProps<TextFieldProps>();
const emit = defineEmits(['update:modelValue']);

 
const { meta_field, name } = props;
const key =
  meta_field?.field_name as keyof RegisterStep['supplierCertificates'];

const outlinedFilled =
  meta_field.design === 'outlined-filled' ? 'bg-grey-5' : '';
const inlineLabel =
  meta_field.label_style === 'inline' ? 'flex q-col-gutter-xl' : '';
const additionalClass = `${outlinedFilled} ${inlineLabel}`;

const fileRef = ref<QFile | null>(null);
const dialog = ref(false);
const currentPdfUrl = ref('');
const status = toRef(supplierUploadStatus.value, key);
if (!status.value) {
  status.value = {};
}
const modelValue = toRef(props, 'modelValue');

const asterisk = computed(() => {
  return props.meta_field.required ? '*' : '';
});

const isDisable = computed(() => {
  if (status.value) {
    return status.value['status'] === 'loading' || !props.modelValue;
  } else {
    return false;
  }
});

const displayFileName = computed(() => {
  if (!props.modelValue) {
    if (props.label) return props.label;
    if (meta_field.title) return i18n.t(`${meta_field.title}`);
    if (meta_field.placeholder) return meta_field.placeholder;
    return '';
  }
  const file = props.modelValue;
  return file.name;
});

const renameFile = (originalFile: File, newName: string): File => {
  return new File([originalFile], newName, {
    type: originalFile.type,
    lastModified: originalFile.lastModified,
  });
};

const previewFile = () => {
  if (isDisable.value) return;
  const file = props.modelValue;
  if (!file) return;
  currentPdfUrl.value = URL.createObjectURL(file);
  dialog.value = true;
};

const pickFile = () => {
  if (!fileRef.value) return;
  fileRef.value.pickFiles();
};

const updateFile = async (event: File) => {
  status.value['status'] = 'loading';
  await uploadFile(
    $route.params.id as string,
    event,
    props.meta_field?.input_type as any,
  )
    .then((res) => {
      // validating
      if (!res.success) throw new Error(res.message);
      if (props.meta_field?.input_type === 'certificate_of_insurance') {
        formConfigure.value.insurance_expired_at =
          res?.data?.minimum_expiration_date;
      }
      const file = renameFile(event, res.data.document_name);
      emit('update:modelValue', file);
      // show warning but enable to upload
      if (!res.data.is_valid) throw res;
      status.value['status'] = 'uploaded';
    })
    .catch((e: any) => {
      status.value['status'] = 'error';
      status.value['errorMessage'] = JSON.parse(e.data.error_message);
    })
    .finally(() => {
      if (!fileRef.value) return;
      fileRef.value.resetValidation();
    });
};

const clearFile = async () => {
  if (isDisable.value) return;
  status.value['status'] = 'loading';
  const response = await deleteFile(
    $route.params.id as string,
    props.meta_field?.input_type as any,
  );

  if (response.success === false) {
    status.value['status'] = 'error';
    status.value['errorMessage'] = [response.message];
    return;
  }

  status.value['status'] = 'none';
  emit('update:modelValue', null);
};
</script>
<style scoped lang="scss">
:deep(label.row.items.center) {
  display: none;
}
.spin {
  animation-name: spin;
  animation-iteration-count: infinite;
  animation-timing-function: linear;
  animation-duration: 5000ms;
}
@keyframes spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
:deep(.q-field--error .q-field__control .q-field__native),
:deep(.q-field__control.text-negative .q-field__native) {
  color: var(--q-negative) !important;
}
:deep(.q-field__label) {
  transform: none !important;
}
.error-listing {
  list-style: disc;
  padding: 0 10px;
  margin: 0;
  color: $warning;
}
.listing-header {
  padding: 0;
  margin: 0;
  color: $warning;
}
</style>
